// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);
        unlockTime = bound(unlockTime, 0, type(uint256).max);

        vm.deal(actor, amount);
        uint256 tsBefore = block.timestamp;
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (uint256 storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime >= tsBefore);
    }
}
